mapper.select:
select project.*,
project.business_project_bid_manager_finish_date as projectBidManagerFinishDate, project.business_project_bid_manager_actual_finish_date as projectBidManagerActualFinishDate, project.business_crm_project_bid_status as crmProjectBidStatus, project.business_project_bid_manager_user_id as projectInformantUserIds,
project.technology_project_bid_manager_finish_date as projectBidManagerFinishDate, project.technology_project_bid_manager_actual_finish_date as projectBidManagerActualFinishDate, project.technology_crm_project_bid_status as crmProjectBidStatus, project.technology_project_bid_manager_user_id as projectInformantUserIds,
project.devise_project_bid_manager_finish_date as projectBidManagerFinishDate, project.devise_project_bid_manager_actual_finish_date as projectBidManagerActualFinishDate, project.devise_crm_project_bid_status as crmProjectBidStatus, project.devise_project_bid_manager_user_id as projectInformantUserIds,
enter.business_name as crmEnterpriseWarehousingName, project_config.name as structureTypeConfigurationName, dept.name as departmentName from crm_project_information_warehousing as project left join crm_enterprise_warehousing as enter on enter.id = project.crm_enterprise_warehousing_id and enter.bool_delete_enum =0 left join sys_department as dept on dept.id = project.department_id and dept.bool_delete_enum =0 left join crm_project_information_config as project_config on project_config.id = project.structure_type_configuration_id and project_config.bool_delete_enum =0
project.bool_delete_enum =0
and date(project.informant_date_time) >= date(#{startDate})
and date(project.informant_date_time) <= date(#{endDate})
and project.country_id = #{countryId}
and project.province_id = #{provinceId}
and project.city_id = #{cityId}
and project.region_id = #{regionId}
and project.structure_type_configuration_id = #{structureTypeConfigurationId}
and project.department_id = #{departmentId}
and project.project_name like concat('%',#{projectName},'%')
and enter.business_name like concat('%',#{crmEnterpriseWarehousingName},'%')
and project.informant_user_name like concat('%',#{projectInformantUserName},'%')
and project.id in
#{projectId}
and (project.information_operator_dept_id IN
#{deptId}
or project.information_operator_user_id = #{userId})
and project.information_operator_dept_id IN
#{deptId}
-- 只查看自己的内容 and project.information_operator_user_id = #{userId}
order by project.informant_date_time desc

